    /// # Errors
    ///
    /// This function will return an error if the user lacks permission change
    /// attributes on the underlying file. It may also return an error in other
    /// os-specific unspecified cases.
    ///
    /// # Examples
    ///
    /// ```no_run
    /// use tokio::fs::File;
    ///
    /// # async fn dox() -> std::io::Result<()> {
    /// let file = File::open("foo.txt").await?;
    /// let mut perms = file.metadata().await?.permissions();
    /// perms.set_readonly(true);
    /// file.set_permissions(perms).await?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn set_permissions(&self, perm: Permissions) -> io::Result<()> {
        let std = self.std.clone();
        asyncify(move || std.set_permissions(perm)).await
    }

    /// Set the maximum buffer size for the underlying [`AsyncRead`] / [`AsyncWrite`] operation.
    ///
    /// Although Tokio uses a sensible default value for this buffer size, this function would be
    /// useful for changing that default depending on the situation.
    ///
    /// # Examples
    ///
    /// ```no_run
    /// use tokio::fs::File;
    /// use tokio::io::AsyncWriteExt;
    ///
    /// # async fn dox() -> std::io::Result<()> {
    /// let mut file = File::open("foo.txt").await?;
    ///
    /// // Set maximum buffer size to 8 MiB
    /// file.set_max_buf_size(8 * 1024 * 1024);
    ///
    /// let mut buf = vec![1; 1024 * 1024 * 1024];
    ///
    /// // Write the 1 GiB buffer in chunks up to 8 MiB each.
    /// file.write_all(&mut buf).await?;
    /// # Ok(())
    /// # }
    /// ```
    pub fn set_max_buf_size(&mut self, max_buf_size: usize) {
        self.max_buf_size = max_buf_size;
    }
}

impl AsyncRead for File {
    fn poll_read(
        self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        dst: &mut ReadBuf<'_>,
    ) -> Poll<io::Result<()>> {
        ready!(crate::trace::trace_leaf(cx));
        let me = self.get_mut();
        let inner = me.inner.get_mut();

        loop {
            match inner.state {
                State::Idle(ref mut buf_cell) => {
                    let mut buf = buf_cell.take().unwrap();

                    if !buf.is_empty() {
                        buf.copy_to(dst);
                        *buf_cell = Some(buf);
                        return Poll::Ready(Ok(()));
                    }

                    let std = me.std.clone();
                    let dst_capacity = dst.buf.len();
                    let dst_filled = dst.filled;
                    let dst_remaining = if dst_capacity > dst_filled {
                        dst_capacity - dst_filled
                    } else {
                        0
                    };

                    let configured_max = me.max_buf_size;
                    let max_buf_size = if dst_remaining > configured_max {
                        configured_max
                    } else {
                        dst_remaining
                    };

                    inner.state = State::Busy(spawn_blocking(move || {
                        let current_len = buf.buf.len();
                        let current_pos = buf.pos;
                        let logical_len = if current_len > current_pos {
                            current_len - current_pos
                        } else {
                            0
                        };
                        assert_eq!(logical_len, 0);

                        buf.buf.reserve(max_buf_size);
                        let spare = buf.buf.spare_capacity_mut();
                        let uninit = &mut spare[..max_buf_size];
                        let slice = unsafe {
                            &mut *(uninit as *mut [MaybeUninit<u8>] as *mut [u8])
                        };

                        let read_res = loop {
                            match std::io::Read::read(&mut &*std, slice) {
                                Err(ref err) if err.kind() == io::ErrorKind::Interrupted => {
                                    continue;
                                }
                                Err(err) => break Err(err),
                                Ok(read_n) => break Ok(read_n),
                            }
                        };

                        let res = match read_res {
                            Ok(n) => {
                                unsafe {
                                    buf.buf.set_len(n);
                                }
                                assert_eq!(buf.pos, 0);
                                Ok(n)
                            }
                            Err(err) => {
                                buf.buf.clear();
                                assert_eq!(buf.pos, 0);
                                Err(err)
                            }
                        };
                        (Operation::Read(res), buf)
                    }));
                }
                State::Busy(ref mut rx) => {
                    let (op, mut buf) = match Pin::new(rx).poll(cx) {
                        Poll::Pending => return Poll::Pending,
                        Poll::Ready(Err(join_err)) => {
                            let io_err: io::Error = join_err.into();
                            match io_err.kind() {
                                io::ErrorKind::Other => return Poll::Ready(Err(io_err)),
                                io::ErrorKind::Interrupted => {
                                    return Poll::Ready(Err(io_err))
                                }
                                io::ErrorKind::UnexpectedEof => {
                                    return Poll::Ready(Err(io_err))
                                }
                                _ => return Poll::Ready(Err(io_err)),
                            }
                        }
                        Poll::Ready(Ok(pair)) => pair,
                    };

                    match op {
                        Operation::Read(Ok(_read_n)) => {
                            let buf_len = buf.buf.len();
                            let buf_pos = buf.pos;
                            let available = if buf_len > buf_pos {
                                buf_len - buf_pos
                            } else {
                                0
                            };
                            let dst_capacity = dst.buf.len();
                            let dst_filled = dst.filled;
                            let dst_initialized = dst.initialized;
                            let space = if dst_capacity > dst_filled {
                                dst_capacity - dst_filled
                            } else {
                                0
                            };
                            let n_copy = if available > space {
                                space
                            } else {
                                available
                            };
                            let init_space = if dst_initialized > dst_filled {
                                dst_initialized - dst_filled
                            } else {
                                0
                            };

                            if n_copy == 0 {
                                if buf_pos == buf_len {
                                    if buf.buf.is_empty() {
                                        buf.pos = 0;
                                    } else {
                                        buf.buf.truncate(0);
                                        buf.pos = 0;
                                    }
                                }
                                inner.state = State::Idle(Some(buf));
                                return Poll::Ready(Ok(()));
                            }

                            if n_copy <= init_space {
                                if n_copy <= 64 {
                                    let src = &buf.buf[buf_pos..buf_pos + n_copy];
                                    let end = dst_filled + n_copy;
                                    unsafe {
                                        dst.buf[dst_filled..end]
                                            .as_mut_ptr()
                                            .cast::<u8>()
                                            .copy_from_nonoverlapping(src.as_ptr(), n_copy);
                                    }
                                    dst.filled = end;
                                } else {
                                    let chunk_size = if n_copy <= 4096 { 512 } else { 8192 };
